def encode_v(atoms, p, agg='sqrt'):
    A = torch.stack(atoms); n = len(atoms)
    s1 = mlp(A, p+'.mlp1').sum(0)
    s1 = {'sqrt': s1/math.sqrt(n), 'mean': s1/n, 'sum': s1}[agg]
    return ln(mlp(s1 + lin(torch.tensor([math.log(1+n)]), p+'.size'), p+'.mlp2'), p+'.norm')
